namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string DepartmentCode { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    List<Course> GetCourses(string? searchTerm = null, string? departmentCode = null);
    List<Course> GetFeaturedCourses();
    Course? GetCourseById(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "HIST", Name = "History" },
        new() { Code = "BIO", Name = "Biology" }
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior programming experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience. Her research focuses on CS education and making computing accessible to all students.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, hash tables, graphs) and algorithm design techniques (sorting, searching, dynamic programming). Emphasizes analysis of time and space complexity.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. James Park",
            InstructorBio = "Dr. Park is an associate professor specializing in algorithm design and optimization. He previously worked at Google Research and has published extensively on graph algorithms."
        },
        new()
        {
            Id = 3, CourseCode = "CS 310", Title = "Database Systems",
            Description = "Introduction to relational database design, SQL, normalization theory, transaction processing, and query optimization. Includes a semester-long project building a database-backed web application.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Maria Santos",
            InstructorBio = "Dr. Santos brings industry experience from Oracle and Amazon to the classroom. She specializes in distributed database systems and data engineering."
        },
        new()
        {
            Id = 4, CourseCode = "MATH 151", Title = "Calculus I",
            Description = "Covers limits, continuity, derivatives of algebraic and transcendental functions, applications of differentiation, and an introduction to integration. Suitable for STEM majors.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH",
            InstructorName = "Prof. Robert Liu",
            InstructorBio = "Prof. Liu has been teaching calculus for over 20 years and is a recipient of the university's Distinguished Teaching Award. He is the author of a widely used calculus textbook.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors, inner product spaces, and applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "MATH",
            InstructorName = "Dr. Sarah Kim",
            InstructorBio = "Dr. Kim's research lies at the intersection of linear algebra and machine learning. She holds a joint appointment with the Data Science Institute."
        },
        new()
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational dynamics, oscillations, and the laws of thermodynamics. Calculus-based.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Michael Torres",
            InstructorBio = "Dr. Torres is an experimental physicist whose research involves particle detector development. He is passionate about interactive physics demonstrations.",
            IsFeatured = true
        },
        new()
        {
            Id = 7, CourseCode = "ENG 101", Title = "Composition and Rhetoric",
            Description = "Develops skills in academic writing, argumentation, critical reading, and research methodology. Students produce multiple essay drafts and a final research paper.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "ENG",
            InstructorName = "Prof. Linda Nguyen",
            InstructorBio = "Prof. Nguyen is an award-winning author and writing instructor. She has published two novels and serves as editor of the university's literary journal."
        },
        new()
        {
            Id = 8, CourseCode = "ENG 220", Title = "American Literature",
            Description = "Survey of American literary works from the colonial period through the 21st century. Examines major movements including Transcendentalism, Realism, Modernism, and contemporary fiction.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentCode = "ENG",
            InstructorName = "Dr. David Brown",
            InstructorBio = "Dr. Brown specializes in 20th-century American fiction and has published critical studies on Faulkner, Morrison, and DeLillo."
        },
        new()
        {
            Id = 9, CourseCode = "HIST 105", Title = "World History to 1500",
            Description = "A global survey of human civilizations from prehistory through the late medieval period. Covers the development of agriculture, empires, trade networks, religions, and cultural exchange.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Emily Watson",
            InstructorBio = "Dr. Watson is a historian of the ancient Mediterranean world. She has conducted archaeological fieldwork in Greece and Turkey.",
            IsFeatured = true
        },
        new()
        {
            Id = 10, CourseCode = "BIO 110", Title = "Principles of Biology",
            Description = "Introduction to cell biology, genetics, evolution, ecology, and organismal biology. Includes weekly laboratory sessions with hands-on experiments and microscopy.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Tue 3:00–5:50 PM", DepartmentCode = "BIO",
            InstructorName = "Dr. Rachel Green",
            InstructorBio = "Dr. Green is a molecular biologist whose research focuses on gene regulation in plant systems. She received an NSF CAREER award for her work on sustainable agriculture."
        },
        new()
        {
            Id = 11, CourseCode = "CS 450", Title = "Machine Learning",
            Description = "Fundamentals of machine learning including supervised and unsupervised learning, neural networks, decision trees, support vector machines, and model evaluation. Includes hands-on projects using Python and scikit-learn.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience. Her research focuses on CS education and making computing accessible to all students.",
            IsFeatured = true
        },
        new()
        {
            Id = 12, CourseCode = "MATH 310", Title = "Probability and Statistics",
            Description = "Probability theory, random variables, common distributions, expectation, hypothesis testing, confidence intervals, and regression analysis. Applications drawn from science and engineering.",
            Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentCode = "MATH",
            InstructorName = "Dr. Sarah Kim",
            InstructorBio = "Dr. Kim's research lies at the intersection of linear algebra and machine learning. She holds a joint appointment with the Data Science Institute."
        }
    ];

    public List<Department> GetDepartments() => Departments;

    public List<Course> GetCourses(string? searchTerm = null, string? departmentCode = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public List<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        var course = GetCourseById(request.CourseId);
        return course is not null;
    }
}

