@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@rendermode InteractiveServer
@inject ICatalogService CatalogService

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="row mb-4 g-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses, instructors…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartment">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Code">@dept.Name (@dept.Code)</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>

    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var course in filteredCourses)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <span class="badge bg-primary mb-2">@course.DepartmentCode</span>
                        <span class="badge bg-secondary mb-2">@course.Credits Credits</span>
                        <h5 class="card-title">@course.CourseCode &mdash; @course.Title</h5>
                        <p class="card-text"><small><strong>Schedule:</strong> @course.Schedule</small></p>
                        <p class="card-text"><small><strong>Instructor:</strong> @course.InstructorName</small></p>
                    </div>
                    <div class="card-footer bg-transparent border-0 pb-3">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        <a href="/enroll?courseId=@course.Id" class="btn btn-primary btn-sm ms-2">Enroll</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "department")]
    public string? InitialDepartment { get; set; }

    private List<Department> departments = [];
    private List<Course> filteredCourses = [];

    private string _searchTerm = string.Empty;
    private string _selectedDepartment = string.Empty;

    private string searchTerm
    {
        get => _searchTerm;
        set
        {
            _searchTerm = value;
            ApplyFilters();
        }
    }

    private string selectedDepartment
    {
        get => _selectedDepartment;
        set
        {
            _selectedDepartment = value;
            ApplyFilters();
        }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();

        if (!string.IsNullOrWhiteSpace(InitialDepartment))
        {
            _selectedDepartment = InitialDepartment;
        }

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.GetCourses(
            string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm,
            string.IsNullOrWhiteSpace(selectedDepartment) ? null : selectedDepartment);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartment = string.Empty;
        ApplyFilters();
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>Enroll — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@enrollmentRequest.FullName</strong>. Your enrollment request for
            <strong>@GetCourseName(enrollmentRequest.CourseId)</strong> has been received.</p>
        <hr />
        <p class="mb-0">
            <a href="/courses" class="alert-link">Browse more courses</a> or
            <a href="/enroll" class="alert-link">submit another request</a>.
        </p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-7">
            <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" class="form-control" @bind-Value="enrollmentRequest.FullName" />
                    <ValidationMessage For="() => enrollmentRequest.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="enrollmentRequest.StudentId" />
                    <ValidationMessage For="() => enrollmentRequest.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="enrollmentRequest.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.CourseCode — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => enrollmentRequest.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>

        <div class="col-lg-5 mt-4 mt-lg-0">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">How It Works</h5>
                    <ol class="mb-0">
                        <li class="mb-2">Select a course from the list or browse the <a href="/courses">course catalog</a> first.</li>
                        <li class="mb-2">Fill out your name and student ID.</li>
                        <li class="mb-2">Submit the form. You'll receive confirmation once processed.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest enrollmentRequest { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (PreselectedCourseId.HasValue && enrollmentRequest.CourseId == 0)
        {
            enrollmentRequest.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = CatalogService.SubmitEnrollmentRequest(enrollmentRequest);
    }
}

